if k<=0: raise ValueError('RRF k must be positive')
scores={}
for ranked_ids in rankings:
    seen=set()
    for rank,cid in enumerate(ranked_ids,1):
        if cid in seen: continue
        seen.add(cid);scores[cid]=scores.get(cid,0)+1/(k+rank)
return sorted(scores,key=lambda x:(-scores[x],x))

