packet={'rules':RULES,'task':task,'preferences':[m for m in memories if m['kind']=='preference'],
        'evidence':[],'budget_unit':'utf8_bytes'}
dropped=[];seen=set()
if packet_size(packet)>budget_bytes:raise ValueError('Task and mandatory instructions exceed context budget')
ordered=sorted(evidence,key=lambda e:0 if e['type']=='sql' else 1)
for item in ordered:
    if item['id'] in seen:continue
    seen.add(item['id'])
    candidate={**packet,'evidence':packet['evidence']+[item]}
    if packet_size(candidate)<=budget_bytes:packet=candidate
    elif item['type']=='sql':
        raise ValueError('Required SQL evidence exceeds budget; aggregate with an explicit query, do not truncate')
    else:dropped.append({'id':item['id'],'reason':'context_budget'})
return packet,dropped
